list_order_flags.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.orderFlags().listOrderFlags(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("order_flags")) {
    Map<?, ?> orderFlag = (Map<?, ?>) row;
    System.out.println(orderFlag.get("id") + " " + orderFlag.get("name") + " " + orderFlag.get("color"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

